<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class PujaBooking extends Model { protected $fillable=['booking_number','user_id','puja_id','booking_slot_id','name','email','mobile','birth_date','birth_time','birth_place','address','people_count','puja_location','special_requirements','message','amount','status','reserved_until']; protected function casts():array{return ['birth_date'=>'date','reserved_until'=>'datetime'];} public function puja(){return $this->belongsTo(Puja::class);} public function slot(){return $this->belongsTo(BookingSlot::class,'booking_slot_id');} public function user(){return $this->belongsTo(User::class);} public function payments(){return $this->morphMany(Payment::class,'payable');} }
